{"facts": [
  {"evidence": [4, 16], "text": "The reality-virtuality continuum is a scale."},
  {"evidence": [5], "text": "The real environment is at one extreme of the reality-virtuality continuum where nothing is virtual."},
  {"evidence": [6, 7, 17], "text": "The virtual environment is at the other extreme of the reality-virtuality continuum where nothing is real."},
  {"evidence": [8], "text": "The interval between the two extremes of the reality-virtuality continuum contains augmented reality and augmented virtuality."},
  {"evidence": [8, 10, 13], "text": "Augmented reality is the augmentation of the real world with virtual content."},
  {"evidence": [8, 9, 11, 12], "text": "Augmented virtuality is the augmentation of the virtual world with real world content."},
  {"evidence": [14, 18], "text": "The entire space between the virtual environment and the real environment in the reality-virtuality continuum is broadly sometimes referred to as mixed reality."}
]}

{"facts": [
  {"evidence": [10], "text": "Extended reality is a term that is often heard."},
  {"evidence": [5, 11, 12], "text": "Virtual reality and augmented reality are terms included in the course title."},
  {"evidence": [13], "text": "Mixed reality is a term that is heard nowadays."},
  {"evidence": [41, 42], "text": "Finding answers to questions regarding virtual reality, augmented reality, extended reality, and mixed reality is one of the main objectives of the course."}
]}

{
"facts": [
{"evidence": [6, 10, 12, 39], "text": "Extended reality is an umbrella term."},
{"evidence": [6, 7, 13, 16, 38], "text": "Extended reality encapsulates all immersive technologies."},
{"evidence": [6, 9, 13, 39], "text": "Augmented reality, virtual reality, and mixed reality are immersive technologies."},
{"evidence": [11], "text": "Extended reality is not a reference to a specific technology."},
{"evidence": [18, 19, 20, 22], "text": "The variable X in the term extended reality can take any value, and each of those values forms a technology."},
{"evidence": [28], "text": "The variable X in the term extended reality refers to all present or future immersive technologies."},
{"evidence": [31, 34, 35, 36], "text": "Immersive technology is a technology in which a user experiences an environment through sensory organs in such a way that they fail to distinguish that environment from the real environment and perceive the experience as real."}
]
}

{"facts": [
    {"evidence": [2], "text": "The terms virtual reality, augmented reality, mixed reality, and extended reality are becoming common, but they can refer to different things for different people."},
    {"evidence": [4, 5, 6], "text": "To some people, the terms virtual reality, augmented reality, mixed reality, and extended reality immediately bring to mind a magical environment containing imaginary, magical, or unnatural objects."},
    {"evidence": [11, 12, 16], "text": "Some people perceive 3D or 4D movie theaters showing documentaries on extinct animals as examples of augmented reality and virtual reality."},
    {"evidence": [18, 20], "text": "The most common public perception of virtual reality is a user wearing a headset and performing actions in a virtual world."},
    {"evidence": [19], "text": "A headset is worn on the head, blocks vision, and transports the user to a virtual world experienced through the headset."},
    {"evidence": [21, 22], "text": "Many people perceive augmented reality as viewing the real world on a device screen while seeing virtual objects that do not exist in the real world."},
    {"evidence": [30, 31], "text": "Some people perceive augmented reality as a way to see things in different ways, such as viewing the internal skeletal structure or the internal vein network of a leg instead of only the skin."}
]}
